const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Gobi Desert boundary (approximate)
  const gobiBoundary = ee.Geometry.Rectangle([100, 40, 120, 45]);

  // February 2019
  const col2019 = ee.ImageCollection('MODIS/006/MOD04_L2')
    .filterDate('2019-02-01', '2019-03-01')
    .filterBounds(gobiBoundary);

  const size2019 = col2019.size().getInfo();
  console.log(`Feb 2019 Images: ${size2019}`);

  if (size2019 === 0) {
    console.log('No MODIS data for Feb 2019');
    console.log('C1');
    return;
  }

  // February 2020
  const col2020 = ee.ImageCollection('MODIS/006/MOD04_L2')
    .filterDate('2020-02-01', '2020-03-01')
    .filterBounds(gobiBoundary);

  const size2020 = col2020.size().getInfo();
  console.log(`Feb 2020 Images: ${size2020}`);

  if (size2020 === 0) {
    console.log('No MODIS data for Feb 2020');
    console.log('C1');
    return;
  }

  // Composite and extract AOD (Optical_Depth_Land_2p1um = 550nm equivalent)
  const mean2019 = col2019
    .select('Optical_Depth_Land_2p1um')
    .mean()
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: gobiBoundary,
      scale: 10000,
      maxPixels: 1e9
    })
    .get('Optical_Depth_Land_2p1um')
    .getInfo();

  const count2019 = col2019
    .select('Optical_Depth_Land_2p1um')
    .mean()
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: gobiBoundary,
      scale: 10000,
      maxPixels: 1e9
    })
    .get('Optical_Depth_Land_2p1um')
    .getInfo();

  console.log(`2019 AOD: ${mean2019 !== null ? (mean2019 * 0.001).toFixed(3) : 'null'} (pixels: ${count2019})`);

  const mean2020 = col2020
    .select('Optical_Depth_Land_2p1um')
    .mean()
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: gobiBoundary,
      scale: 10000,
      maxPixels: 1e9
    })
    .get('Optical_Depth_Land_2p1um')
    .getInfo();

  const count2020 = col2020
    .select('Optical_Depth_Land_2p1um')
    .mean()
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: gobiBoundary,
      scale: 10000,
      maxPixels: 1e9
    })
    .get('Optical_Depth_Land_2p1um')
    .getInfo();

  console.log(`2020 AOD: ${mean2020 !== null ? (mean2020 * 0.001).toFixed(3) : 'null'} (pixels: ${count2020})`);

  // Validation
  if (mean2019 === null || mean2020 === null || isNaN(mean2019) || isNaN(mean2020)) {
    console.log('C3');
    return;
  }

  if (count2019 === 0 || count2020 === 0) {
    console.log('C2');
    return;
  }

  // Scale from int16 (raw) to actual AOD (divide by 1000)
  const aod2019 = mean2019 * 0.001;
  const aod2020 = mean2020 * 0.001;

  // Check physical validity
  if (aod2019 < -0.5 || aod2019 > 5 || aod2020 < -0.5 || aod2020 > 5) {
    console.log('C3');
    return;
  }

  console.log(`Comparison: 2020 (${aod2020.toFixed(3)}) vs 2019 (${aod2019.toFixed(3)})`);

  if (aod2020 > aod2019) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
